public class CausalMessageBuffer {
    private final Map<String, Long> vectorClock = new ConcurrentHashMap<>();
    private final BlockingQueue<Message> inboundQueue = new LinkedBlockingQueue<>();

    public void deliverMessage(Message msg) throws InterruptedException {
        while (!satisfiesCausality(msg)) {
            Thread.yield(); // Wait for causal dependencies
        }
        applyMessage(msg);
    }

    private boolean satisfiesCausality(Message msg) {
        // Verify sender's logical clock matches expected sequential dependency
        long currentSenderTime = vectorClock.getOrDefault(msg.getSenderId(), 0L);
        return msg.getSequenceNumber() == currentSenderTime + 1;
    }

    private void applyMessage(Message msg) {
        vectorClock.put(msg.getSenderId(), msg.getSequenceNumber());
        System.out.println("Applied: " + msg.getPayload());
    }
}
